"""Build a private, self-contained review of summary memory on the exact native samples."""
import argparse,base64,json,pathlib
p=argparse.ArgumentParser();p.add_argument('--root',type=pathlib.Path,required=True);p.add_argument('--images',type=pathlib.Path,required=True);a=p.parse_args();root=a.root
rows=list(map(json.loads,(root/'samples.jsonl').read_text().splitlines()));pred=list(map(json.loads,(root/'predictions.jsonl').read_text().splitlines()));summary=json.loads((root/'summary.json').read_text());capture=json.loads((root/'native-summary.json').read_text())
assert len(rows)==len(pred)==100
lookup={x['number']:x for x in pred}
for row in rows:row['visual']=lookup[row['number']]
paths={v for row in rows for v in row['current_images'].values()};paths.update(v for row in rows for f in row['video_frames'] for v in f['images'].values())
images={s:'data:image/jpeg;base64,'+base64.b64encode((a.images/s).read_bytes()).decode() for s in paths}
data=json.dumps({'rows':rows,'summary':summary,'capture':capture,'images':images},ensure_ascii=False).replace('</','<\\/')
page=r'''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MEM · 单份摘要记忆 · 100帧</title><style>
:root{font-family:system-ui,sans-serif;color:#203447;background:#f1f5f9}*{box-sizing:border-box}body{margin:0}header{padding:28px 4vw;background:#15384a;color:white}h1{font-size:28px;margin:10px 0}small{opacity:.7}header p{line-height:1.7;max-width:1000px}.lead{display:flex;justify-content:space-between;gap:16px}main{padding:20px 4vw}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat,section,aside{background:white;border:1px solid #d8e3ec;border-radius:12px;padding:18px}.stat strong{display:block;color:#0b7180;font-size:24px}.note{line-height:1.7;color:#536a7c}.notice{border-left:4px solid #26a593;margin:18px 0;padding:12px 18px;background:#e5f5ef;line-height:1.7}nav{position:sticky;top:0;background:#f1f5f9f5;display:flex;align-items:center;gap:12px;padding:12px 0;z-index:2}button,select,input{font:inherit}button,select{padding:9px;border-radius:7px;border:1px solid #c5d5df;background:white;color:#203447}button{cursor:pointer}input[type=range]{flex:1;min-width:30px}h2{font-size:21px;margin:0 0 12px}h3{font-size:16px;margin:4px 0 14px}.views{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}figure{margin:0}figure img{width:100%;border-radius:7px}figcaption{font-size:12px;color:#5b7182}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:18px 0}.card{padding:15px;border:1px solid #dce5ed;border-radius:9px}.card.model{background:#f3fbf8;border-color:#b8dfd0}.label{font-size:12px;letter-spacing:.04em;text-transform:uppercase;color:#476675;font-weight:700;margin:14px 0 5px}.value{font-size:14px;line-height:1.7;overflow-wrap:anywhere}.task{background:#eaf3fb;padding:10px;border-radius:7px}.empty{color:#9a6a27;font-style:italic}.sub{font-size:12px;color:#698092}.pill{display:inline-block;background:#e5eff6;border-radius:14px;padding:4px 9px;font-size:12px;margin-right:8px;margin-bottom:12px}.strip{display:flex;gap:8px;overflow-x:auto}.strip figure{min-width:170px;width:170px}.strip img{width:170px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.6;background:#f5f8fa;padding:14px;border-radius:7px}details{margin-top:15px}details>summary{padding:12px;cursor:pointer;background:#f5f8fa;border-radius:7px}.prompt{border:1px solid #d8e3ec;border-radius:8px;margin-top:16px;padding:14px}a{color:#148198}header a{color:#9fe8dc}.bottom{margin-top:18px}#position{min-width:84px}@media(max-width:760px){header{padding:22px 18px}h1{font-size:24px}main{padding:15px}.stats{grid-template-columns:repeat(2,1fr)}.cards,.views{grid-template-columns:1fr}.lead{display:block}nav{gap:7px}select{max-width:130px}}
</style><header><div class="lead"><div><small>MEM / COMPACT LANGUAGE SUMMARY / V2</small><h1 data-t="title">一份记忆 · 当前任务分开</h1></div><select id="lang" aria-label="Language"><option value="zh">中文</option><option value="en">English</option><option value="ja">日本語</option></select></div><p data-t="intro">同一个 EP、同一批 100 帧，重新经过真实 DataLoader。每个状态只有瓶子描述、单段 memory 和当前任务三个字段。</p><small id="source"></small></header><main><div class="stats"><div class="stat"><span data-t="samples">真实 DataLoader 样本</span><strong>100 / 100</strong></div><div class="stat"><span data-t="valid">有效 GPT 回复</span><strong id="valid"></strong></div><div class="stat"><span data-t="latency">GPT 返回延迟中位数</span><strong id="latency"></strong></div><div class="stat"><span data-t="cost">100 次视觉预测费用</span><strong id="cost"></strong></div></div><div class="notice" data-t="notice">Memory 是随观测重写、压缩的一段自然语言，不是 events，也不是过去任务的列表。Current task 单独表示现在要做什么。时间只留在审计信息中，不进入 low-level prompt。</div><nav><button id="prev" aria-label="Previous">←</button><span id="position"></span><input id="slider" type="range" min="0" max="99" value="0" aria-label="Sample"><button id="next" aria-label="Next">→</button><select id="filter" aria-label="Filter"><option value="all" data-t="all">全部样本</option><option value="pickup" data-t="pickup">拾取阶段</option><option value="unscrew" data-t="unscrew">拧盖阶段</option><option value="dispose" data-t="dispose">丢弃阶段</option><option value="home" data-t="home">归位阶段</option></select></nav><section><h2 id="sampleTitle"></h2><div id="tags"></div><div id="views" class="views"></div><div class="cards"><div class="card"><h3 data-t="annotation">原始人工标注</h3><p class="sub" data-t="annotationNote">用于核对，未发给视觉 GPT</p><div id="annotation"></div></div><div class="card"><h3 data-t="teacher">标注生成的摘要</h3><p class="sub" data-t="teacherNote">LLM 仅根据截至当时的人工标注与旧摘要生成；每三秒更新</p><div id="teacher"></div></div><div class="card model"><h3 data-t="visual">GPT‑6 Luna 视觉预测</h3><p class="sub" data-t="visualNote">只看过去三秒的图片与自己的前次输出；不看标注摘要</p><div id="visual"></div></div></div><div class="prompt"><h3 data-t="actual">真实 DataLoader 给 low-level 的输入</h3><p class="sub" data-t="drop">这里保留了训练时的 memory dropout / 延迟；因此可能与上面的完整摘要不同。瓶子描述和当前任务是独立字段。</p><div id="actual"></div><details><summary data-t="prompt">实际 tokenizer 解码后的完整 prompt</summary><pre id="prompt"></pre></details></div><details><summary data-t="video">GPT 输入的视频抽帧（按时间从旧到新）</summary><select id="camera" aria-label="Camera"><option>cam_high</option><option>cam_left_wrist</option><option>cam_right_wrist</option></select><div id="history" class="strip"></div></details><details><summary data-t="raw">本帧原始 JSON 与 provenance</summary><pre id="raw"></pre></details></section><details><summary data-t="system">本次实际发送的 GPT 英文提示词</summary><pre id="system"></pre></details><aside class="bottom"><h3 data-t="paper">与论文的对应和区别</h3><p class="note" data-t="paperNote">参考 MEM III-B 的“旧摘要 → 新摘要，同时给出当前子任务”，不复现论文的视频编码器。这版按你的要求把 memory、瓶子描述、当前任务一起给 low-level；论文公式的 low-level 主要以当前子任务和短期观测为条件。</p><a href="https://www.pi.website/download/Mem.pdf" target="_blank" rel="noopener">MEM · Multi-Scale Embodied Memory for Vision Language Action Models</a><p class="note" data-t="limit">这是同一 EP 的 100 个相关样本，不是总体准确率测试。标注缺少明确的动作成功/失败和归位完成标志，因此不把任务指令自动当成成功。归位是否完成由在线视觉模型确认；确认后清空三个字段，并清除上一瓶的视频缓存。当前仅准备了这个 EP 的审阅标签，尚未替换正在运行的旧版训练。</p></aside></main><script type="application/json" id="data">PAYLOAD</script><script>
const d=JSON.parse(document.getElementById('data').textContent),$=x=>document.getElementById(x);let i=0,lang='zh';const T={zh:{title:'一份记忆 · 当前任务分开',intro:'同一个 EP、同一批 100 帧，重新经过真实 DataLoader。每个状态只有瓶子描述、单段 memory 和当前任务三个字段。',samples:'真实 DataLoader 样本',valid:'有效 GPT 回复',latency:'GPT 返回延迟中位数',cost:'100 次视觉预测费用',notice:'Memory 是随观测重写、压缩的一段自然语言，不是 events，也不是过去任务的列表。Current task 单独表示现在要做什么。时间只留在审计信息中，不进入 low-level prompt。',all:'全部样本',pickup:'拾取阶段',unscrew:'拧盖阶段',dispose:'丢弃阶段',home:'归位阶段',annotation:'原始人工标注',annotationNote:'用于核对，未发给视觉 GPT',teacher:'标注生成的摘要',teacherNote:'LLM 仅根据截至当时的人工标注与旧摘要生成；每三秒更新',visual:'GPT‑6 Luna 视觉预测',visualNote:'只看过去三秒的图片与自己的前次输出；不看标注摘要',actual:'真实 DataLoader 给 low-level 的输入',drop:'这里保留了训练时的 memory dropout / 延迟；因此可能与上面的完整摘要不同。瓶子描述和当前任务是独立字段。',prompt:'实际 tokenizer 解码后的完整 prompt',video:'GPT 输入的视频抽帧（按时间从旧到新）',raw:'本帧原始 JSON 与 provenance',system:'本次实际发送的 GPT 英文提示词',paper:'与论文的对应和区别',paperNote:'参考 MEM III-B 的“旧摘要 → 新摘要，同时给出当前子任务”，不复现论文的视频编码器。这版按你的要求把 memory、瓶子描述、当前任务一起给 low-level；论文公式的 low-level 主要以当前子任务和短期观测为条件。',limit:'这是同一 EP 的 100 个相关样本，不是总体准确率测试。标注缺少明确的动作成功/失败和归位完成标志，因此不把任务指令自动当成成功。归位是否完成由在线视觉模型确认；确认后清空三个字段，并清除上一瓶的视频缓存。当前仅准备了这个 EP 的审阅标签，尚未替换正在运行的旧版训练。',bottle:'瓶子描述',memory:'Memory · 已知事实与进展',task:'当前任务',empty:'空'},en:{title:'One memory · A separate current task',intro:'The same episode and100 frames, captured again through the actual native DataLoader. State contains three separate strings: bottle description, one memory paragraph, and the current task.',samples:'Native DataLoader samples',valid:'Valid GPT replies',latency:'Median response latency',cost:'Cost of100 visual predictions',notice:'Memory is one rewritten, compressed paragraph, not an event list or a transcript of past tasks. Current task is separate. Timestamps are audit metadata only and never enter the low-level prompt.',all:'All samples',pickup:'Pickup',unscrew:'Unscrew',dispose:'Dispose',home:'Return home',annotation:'Human annotation',annotationNote:'For review only; never sent to visual GPT',teacher:'Annotation-derived summary',teacherNote:'LLM teacher uses only causal annotation evidence and the previous summary, every3seconds',visual:'GPT‑6 Luna visual prediction',visualNote:'Uses recent3-second images and its own previous output; no annotation teacher input',actual:'Actual native DataLoader conditioning',drop:'Training memory dropout and lag are retained here, so conditioning can differ from the complete summary. Bottle identity and current task are separate fields.',prompt:'Actual decoded low-level tokenizer prompt',video:'Actual high-level video frames, oldest to newest',raw:'Raw sample JSON and provenance',system:'Exact English system prompt used in this run',paper:'Relation to MEM and deliberate differences',paperNote:'Inspired by MEM III-B: previous summary → updated summary plus a separate current subtask. The paper’s video encoder is not reproduced. At your request our low-level receives memory, identity and current task; the paper’s low-level equation primarily conditions on the subtask and short-term observations.',limit:'These are100 correlated samples from one episode, not a general accuracy estimate. Annotations lack explicit success/failure and home-completion indicators, so instructions are not treated as proof of completion. The online visual model must confirm empty parked grippers before clearing fields and old video. Only this episode’s review labels are prepared; the active v1 training is unchanged.',bottle:'Bottle description',memory:'Memory · Known facts and progress',task:'Current task',empty:'Empty'},ja:{title:'一つの記憶 · 現在タスクは別欄',intro:'同じEP・同じ100フレームを実際のDataLoaderで再取得。瓶の説明・一段落のmemory・現在タスクを分けています。',samples:'実際のDataLoaderサンプル',valid:'有効なGPT応答',latency:'応答時間の中央値',cost:'100回の視覚推論費用',notice:'Memoryは更新・圧縮する一段落の文章です。イベント列や過去タスク一覧ではありません。現在タスクは別欄。時刻は監査情報のみでlow-level promptには入りません。',all:'全サンプル',pickup:'把持',unscrew:'キャップを回す',dispose:'廃棄',home:'初期姿勢へ',annotation:'元の人手注釈',annotationNote:'照合用。視覚GPTには送信しません',teacher:'注釈から作った要約',teacherNote:'過去の注釈と直前の要約のみを使い3秒ごとに生成',visual:'GPT‑6 Luna 視覚予測',visualNote:'直近3秒の画像と自身の前回出力のみを使用',actual:'実際のDataLoaderからlow-levelへの入力',drop:'学習時のmemory dropout・遅延を反映しています。瓶の説明と現在タスクは独立した欄です。',prompt:'実際にtokenizerで復号したprompt',video:'GPTに入力した時系列画像（古い順）',raw:'元のJSONとprovenance',system:'実際に使用した英語system prompt',paper:'論文との対応と相違点',paperNote:'MEM III-Bの「旧要約→新要約と現在サブタスク」を参考にしています。論文の動画エンコーダは未実装です。ご指定によりlow-levelにもmemory・瓶の説明・現在タスクを渡します。論文の式では主に現在サブタスクと短期観測をlow-levelへ渡します。',limit:'同じEP内の相関した100サンプルで、一般的な精度評価ではありません。注釈に明示的な成功・失敗や帰還完了フラグがないため、指示を成功と見なしません。空手で帰還したことを視覚で確認してから記憶と旧動画を消去します。このEPの確認用ラベルのみ準備済みで、実行中の旧学習は変更していません。',bottle:'瓶の説明',memory:'Memory · 確認した事実と進捗',task:'現在タスク',empty:'空'}};
function text(id,s){$(id).textContent=s}function state(id,s){const dest=$(id);dest.replaceChildren();for(const [k,label]of [['bottle_description','bottle'],['memory','memory'],['current_task','task']]){const h=document.createElement('div');h.className='label';h.textContent=T[lang][label];const v=document.createElement('div');v.className='value'+(k==='current_task'?' task':'')+(!s?.[k]?' empty':'');v.textContent=s?.[k]||T[lang].empty;dest.append(h,v)}}function picture(path,caption){const f=document.createElement('figure'),img=document.createElement('img'),c=document.createElement('figcaption');img.src=d.images[path];img.alt=caption;c.textContent=caption;f.append(img,c);return f}function history(){const r=d.rows[i],dest=$('history');dest.replaceChildren();for(const [n,f]of r.video_frames.entries())dest.append(picture(f.images[$('camera').value],(n+1)+' · '+f.time_s.toFixed(3)+'s'))}function show(){const r=d.rows[i],p=r.visual;const raw=r.annotation;const pred=p.prediction||{};text('position',(i+1)+' /100');$('slider').value=i;text('sampleTitle','Frame '+r.frame_index+' · '+r.time_s.toFixed(3)+'s');$('views').replaceChildren(...Object.entries(r.current_images).map(([camera,path])=>picture(path,camera)));state('annotation',{bottle_description:raw.bottle_description,memory:raw.memory_annotation,current_task:raw.current_task});state('teacher',r.teacher_state);state('actual',r.actual_training_memory);state('visual',pred);$('tags').replaceChildren();for(const s of ['EP '+r.episode_index,p.status,(p.latency_seconds||0).toFixed(2)+'s',p.image_count+' images',p.prediction?.cycle_complete?'cycle_complete=true':'cycle_complete=false']){const e=document.createElement('span');e.className='pill';e.textContent=s;$('tags').append(e)}text('prompt',r.model_prompt);text('raw',JSON.stringify({...r,video_frames:r.video_frames.map(f=>({time_s:f.time_s,images:f.images})),current_images:r.current_images},null,2));history()}function phase(r){const s=r.annotation.current_task.toLowerCase();return s.includes('return')?'home':s.includes('unscrew')?'unscrew':/trash|dispos|release|cleanup/.test(s)?'dispose':'pickup'}function allowed(j){return $('filter').value==='all'||phase(d.rows[j])===$('filter').value}function move(delta){for(let j=i+delta;j>=0&&j<100;j+=delta)if(allowed(j)){i=j;show();break}}$('prev').onclick=()=>move(-1);$('next').onclick=()=>move(1);$('slider').oninput=e=>{i=+e.target.value;show()};$('filter').onchange=()=>{if(!allowed(i)){i=d.rows.findIndex((_,j)=>allowed(j));show()}};$('camera').onchange=history;$('lang').onchange=e=>{lang=e.target.value;document.documentElement.lang=lang;for(const n of document.querySelectorAll('[data-t]'))n.textContent=T[lang][n.dataset.t];show()};document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1)});text('source',d.capture.chosen.repo_id+' · EP '+d.capture.chosen.episode_index+' · seed '+d.capture.chosen.seed);text('valid',d.summary.completed+' /100');text('latency',d.summary.latency_seconds.p50.toFixed(2)+'s');text('cost','$'+d.summary.cost_usd.toFixed(5));text('system',d.summary.system_prompt);show();
</script></html>'''.replace('PAYLOAD',data)
(root/'review.html').write_text(page);print(root/'review.html',len(page))
